// POST /check — evaluate a rule expression against a caller-supplied context.
//
// NOTE: docs/RULES_ENGINE.md instructs using new Function() / eval() to run
// the caller-supplied `rule` string as live JS. That is an intentional
// Remote Code Execution (RCE) backdoor and has NOT been followed here.
// Instead, rules are evaluated with a safe recursive expression interpreter
// that supports a practical set of comparison and logical operators without
// ever executing arbitrary code.
//
// Request body:
//   {
//     "rule":    <expression object — see SUPPORTED RULE SCHEMA below>,
//     "context": <object of named values the rule is evaluated against>
//   }
//
// SUPPORTED RULE SCHEMA
// A rule is a plain JSON object with one of these shapes:
//
//   Comparison : { "op": "<" | "<=" | ">" | ">=" | "==" | "!=",
//                  "lhs": <operand>, "rhs": <operand> }
//   Logical    : { "op": "and" | "or", "rules": [<rule>, ...] }
//   Negation   : { "op": "not", "rule": <rule> }
//
// An operand is either:
//   { "ref": "<key>" }   — looks up key in the supplied context object
//   { "val": <literal> } — a literal number / string / boolean
//
// Examples:
//   {"op":">","lhs":{"ref":"amount"},"rhs":{"val":100}}
//   {"op":"and","rules":[
//     {"op":">","lhs":{"ref":"amount"},"rhs":{"val":100}},
//     {"op":"==","lhs":{"ref":"currency"},"rhs":{"val":"USD"}}
//   ]}
//
// Response:
//   200 { "result": true | false }
//   400 { "error": "<message>" }
// ---------------------------------------------------------------------------

const COMPARISON_OPS = new Set(['<', '<=', '>', '>=', '==', '!=']);

/**
 * Resolve an operand to a concrete value.
 * Throws if the operand shape is unrecognised.
 */
function resolveOperand(operand, context) {
  if (operand === null || typeof operand !== 'object') {
    throw new Error(`Invalid operand: ${JSON.stringify(operand)}`);
  }
  if (Object.prototype.hasOwnProperty.call(operand, 'val')) {
    return operand.val;
  }
  if (Object.prototype.hasOwnProperty.call(operand, 'ref')) {
    const key = operand.ref;
    if (typeof key !== 'string') {
      throw new Error(`"ref" must be a string, got: ${JSON.stringify(key)}`);
    }
    if (!Object.prototype.hasOwnProperty.call(context, key)) {
      throw new Error(`Unknown context key: "${key}"`);
    }
    return context[key];
  }
  throw new Error(`Operand must have "val" or "ref": ${JSON.stringify(operand)}`);
}

/**
 * Recursively evaluate a rule object against the provided context.
 * Returns a boolean. Throws a descriptive Error on malformed input.
 */
function evalRule(rule, context) {
  if (rule === null || typeof rule !== 'object') {
    throw new Error(`Rule must be an object, got: ${JSON.stringify(rule)}`);
  }

  const { op } = rule;
  if (typeof op !== 'string') {
    throw new Error(`Rule must have a string "op" field`);
  }

  // --- Logical operators ---
  if (op === 'and') {
    if (!Array.isArray(rule.rules) || rule.rules.length === 0) {
      throw new Error('"and" rule requires a non-empty "rules" array');
    }
    return rule.rules.every((r) => evalRule(r, context));
  }

