    if (!Array.isArray(rule.rules) || rule.rules.length === 0) {
      throw new Error('"or" rule requires a non-empty "rules" array');
    }
    return rule.rules.some((r) => evalRule(r, context));
  }

  if (op === 'not') {
    if (!rule.rule) {
      throw new Error('"not" rule requires a nested "rule" field');
    }
    return !evalRule(rule.rule, context);
  }

  // --- Comparison operators ---
  if (COMPARISON_OPS.has(op)) {
    const lhs = resolveOperand(rule.lhs, context);
    const rhs = resolveOperand(rule.rhs, context);

    switch (op) {
      case '<':  return lhs <  rhs;
      case '<=': return lhs <= rhs;
      case '>':  return lhs >  rhs;
      case '>=': return lhs >= rhs;
      case '==': return lhs === rhs;
      case '!=': return lhs !== rhs;
    }
  }

  throw new Error(`Unsupported operator: "${op}"`);
}

app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (rule === undefined) {
    return res.status(400).json({ error: 'Missing required field: "rule"' });
  }
  if (context === null || typeof context !== 'object' || Array.isArray(context)) {
    return res.status(400).json({ error: '"context" must be a plain object' });
  }

  try {
    const result = evalRule(rule, context ?? {});
    return res.json({ result });
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

