express.application.listen = () => ({ address: () => ({}) });

// Load the app
const app = require('/root/app.js');

// ── helpers ──────────────────────────────────────────────────────────────────
function fakeReq(body) {
  return { body, headers: { 'content-type': 'application/json' } };
}

let passed = 0, failed = 0;

function assert(label, got, expected) {
  const ok = JSON.stringify(got) === JSON.stringify(expected);
  console.log(`${ok ? '✅' : '❌'} ${label}`);
  if (!ok) console.log(`   got:      ${JSON.stringify(got)}\n   expected: ${JSON.stringify(expected)}`);
  ok ? passed++ : failed++;
}

// ── drive the route handler directly ─────────────────────────────────────────
function post(body) {
  return new Promise((resolve) => {
    let statusCode = 200;
    const res = {
      status(s) { statusCode = s; return res; },
      json(data) { resolve({ status: statusCode, body: data }); },
    };
    // find the /check handler
    const layer = app._router.stack.find(l => l.route && l.route.path === '/check');
    layer.route.stack[0].handle(fakeReq(body), res, () => {});
  });
}

// ── tests ─────────────────────────────────────────────────────────────────────
