const t3 = await post({
  rule: { op: 'and', rules: [
    { op: '>', lhs: { ref: 'amount' }, rhs: { val: 100 } },
    { op: '==', lhs: { ref: 'currency' }, rhs: { val: 'USD' } },
  ]},
  context: { amount: 200, currency: 'USD' },
});
