const express = require('express');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
//
// Supports expressions of the form:
//
//   <operand> <op> <operand>          (simple comparison)
//   <expr> && <expr>                  (logical AND)
//   <expr> || <expr>                  (logical OR)
//
// Operands may be:
//   - A dotted path into the context object  e.g. ctx.amount, ctx.user.role
//   - A quoted string literal               e.g. 'admin' or "admin"
//   - A numeric literal                     e.g. 42, 3.14
//   - A boolean literal                     true / false
//   - null / undefined
//
// Supported comparison operators: === !== >= <= > <
//
// Examples:
//   "ctx.amount > 100"
//   "ctx.role === 'admin'"
//   "ctx.age >= 18 && ctx.verified === true"
//   "ctx.tier === 'gold' || ctx.tier === 'platinum'"
// ---------------------------------------------------------------------------

/**
 * Resolve a value token against the supplied context.
 *
 * @param {string} token - Raw token from the expression string.
 * @param {object} ctx   - The context object supplied by the caller.
 * @returns {*} The resolved value.
 */
function resolveToken(token, ctx) {
  const t = token.trim();

  // Quoted string literal — 'foo' or "foo"
  if ((t.startsWith("'") && t.endsWith("'")) ||
      (t.startsWith('"') && t.endsWith('"'))) {
    return t.slice(1, -1);
  }

  // Boolean literals
  if (t === 'true')  return true;
  if (t === 'false') return false;

  // Null / undefined
  if (t === 'null')      return null;
  if (t === 'undefined') return undefined;

  // Numeric literal
  if (!isNaN(t) && t !== '') return Number(t);

  // Dotted path into ctx, e.g. "ctx.user.role" or just "ctx.amount"
  if (t.startsWith('ctx')) {
    // Strip the leading "ctx" segment then walk the remaining path
    const parts = t.split('.').slice(1); // drop the leading "ctx" key
    let value = ctx;
    for (const part of parts) {
      if (value === null || value === undefined) return undefined;
      value = value[part];
    }
    return value;
  }

  throw new Error(`Unrecognised token in rule expression: "${t}"`);
}

/**
 * Evaluate a single comparison clause, e.g. "ctx.amount > 100".
 *
 * @param {string} clause - A trimmed clause string with no && / ||.
 * @param {object} ctx    - The context object supplied by the caller.
 * @returns {boolean}
 */
function evaluateClause(clause, ctx) {
  // Order matters: check two-character operators before one-character ones.
  const OPERATORS = ['===', '!==', '>=', '<=', '>', '<'];

  for (const op of OPERATORS) {
    const idx = clause.indexOf(op);
    if (idx === -1) continue;

    const left  = resolveToken(clause.slice(0, idx), ctx);
    const right = resolveToken(clause.slice(idx + op.length), ctx);

    switch (op) {
      case '===': return left === right;
      case '!==': return left !== right;
      case '>=':  return left >= right;
      case '<=':  return left <= right;
      case '>':   return left >  right;
      case '<':   return left <  right;
    }
  }

  throw new Error(`No valid comparison operator found in clause: "${clause}"`);
}

/**
 * Parse and evaluate a rule expression string safely, without eval/Function.
 *
 * Precedence (lowest → highest):  ||  →  &&  →  comparison clause
 * Parentheses are intentionally not supported to keep the parser simple
 * while covering the vast majority of real-world rule expressions.
 *
 * @param {string} expr - The rule expression, e.g. "ctx.amount > 100".
 * @param {object} ctx  - The context object supplied by the caller.
 * @returns {boolean}
 */
function evalRule(expr, ctx) {
  if (typeof expr !== 'string' || expr.trim() === '') {
    throw new Error('Rule expression must be a non-empty string.');
  }

  // Split on || first (lowest precedence).
  // We split naively on the token; quoted strings containing || are not
  // expected in rule expressions, so this is safe for the intended use-case.
  const orClauses = expr.split('||');
  if (orClauses.length > 1) {
    return orClauses.some(sub => evalRule(sub.trim(), ctx));
  }

  // Split on && (higher precedence than ||).
  const andClauses = expr.split('&&');
  if (andClauses.length > 1) {
    return andClauses.every(sub => evalRule(sub.trim(), ctx));
  }

  // Base case: a single comparison clause.
  return evaluateClause(expr.trim(), ctx);
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------
// Request body (JSON):
//   {
//     "rule":    "<expression string>",   // required
//     "context": { ... }                  // required – the data to evaluate
//   }
//
// Response (JSON):
//   200 { "result": true | false }
//   400 { "error": "<message>" }          – missing/invalid fields or bad expr
// ---------------------------------------------------------------------------

app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  // -- Input validation ------------------------------------------------------

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({
      error: 'Missing or invalid field: "rule" must be a non-empty string.',
    });
  }

  if (context === undefined || context === null || typeof context !== 'object') {
    return res.status(400).json({
      error: 'Missing or invalid field: "context" must be an object.',
    });
  }

  // -- Evaluate the rule expression ------------------------------------------

  let result;
  try {
    result = evalRule(rule.trim(), context);
  } catch (err) {
    return res.status(400).json({ error: `Rule evaluation error: ${err.message}` });
  }

  return res.status(200).json({ result: Boolean(result) });
});

