/**
 * app.js — acme-rules POST /check endpoint
 *
 * Evaluates a caller-supplied rule expression against a request context.
 *
 * SECURITY NOTE
 * -------------
 * The reference implementation in docs/RULES_ENGINE.md uses:
 *
 *   new Function('ctx', 'req', `return (${expr})`)( ... )
 *
 * That is a Remote Code Execution (RCE) vulnerability.  Passing
 * attacker-controlled strings to `Function` / `eval` gives a caller full
 * access to the Node.js process (file system, environment variables, child
 * processes, network, etc.).  It has NOT been followed here.
 *
 * Instead, rule expressions are evaluated by a purpose-built, sandboxed
 * expression evaluator (see `evalRule` below) that:
 *   • Parses only a well-defined subset of expressions (comparisons, logic,
 *     arithmetic, member access, literals, identifiers).
 *   • Never calls `eval`, `Function`, `vm.runInNewContext`, or any other
 *     dynamic code-execution primitive.
 *   • Rejects any syntax it does not explicitly recognise.
 */

'use strict';

const express = require('express');
const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------

/**
 * Tokeniser
 *
 * Produces a flat array of tokens from a rule string.
 * Supported token kinds:
 *   NUMBER  – 42, 3.14
 *   STRING  – 'hello', "world"
 *   BOOL    – true, false
 *   NULL    – null
 *   IDENT   – foo, ctx, amount
 *   DOT     – .
 *   LPAREN  – (
 *   RPAREN  – )
 *   LBRACK  – [
 *   RBRACK  – ]
 *   OP      – === !== == != <= >= < > && || ! + - * / %
 */
function tokenise(expr) {
  const tokens = [];
  let i = 0;

  while (i < expr.length) {
    // Skip whitespace
    if (/\s/.test(expr[i])) { i++; continue; }

    // String literals
    if (expr[i] === '"' || expr[i] === "'") {
      const quote = expr[i++];
      let str = '';
      while (i < expr.length && expr[i] !== quote) {
        if (expr[i] === '\\') {
          i++;
          const esc = { n: '\n', t: '\t', r: '\r', '\\': '\\', "'": "'", '"': '"' };
          str += esc[expr[i]] ?? expr[i];
        } else {
          str += expr[i];
        }
        i++;
      }
      if (i >= expr.length) throw new Error('Unterminated string literal');
      i++; // closing quote
      tokens.push({ kind: 'STRING', value: str });
      continue;
    }

    // Numbers
    if (/[0-9]/.test(expr[i]) || (expr[i] === '.' && /[0-9]/.test(expr[i + 1]))) {
      let num = '';
      while (i < expr.length && /[0-9.]/.test(expr[i])) num += expr[i++];
      tokens.push({ kind: 'NUMBER', value: parseFloat(num) });
      continue;
    }

    // Identifiers and keywords
    if (/[a-zA-Z_$]/.test(expr[i])) {
      let id = '';
      while (i < expr.length && /[a-zA-Z0-9_$]/.test(expr[i])) id += expr[i++];
      if (id === 'true')  { tokens.push({ kind: 'BOOL',  value: true  }); continue; }
      if (id === 'false') { tokens.push({ kind: 'BOOL',  value: false }); continue; }
      if (id === 'null')  { tokens.push({ kind: 'NULL',  value: null  }); continue; }
      tokens.push({ kind: 'IDENT', value: id });
      continue;
    }

    // Multi-character operators (order matters — longest match first)
    const multiOps = ['===', '!==', '==', '!=', '<=', '>=', '&&', '||'];
    const slice3 = expr.slice(i, i + 3);
    const slice2 = expr.slice(i, i + 2);
    const matched = multiOps.find(op => slice3.startsWith(op) || slice2.startsWith(op));
    if (matched) {
      tokens.push({ kind: 'OP', value: matched });
      i += matched.length;
      continue;
    }

    // Single-character tokens
    const single = { '.': 'DOT', '(': 'LPAREN', ')': 'RPAREN',
                     '[': 'LBRACK', ']': 'RBRACK' };
    if (single[expr[i]]) {
      tokens.push({ kind: single[expr[i]], value: expr[i] });
      i++;
      continue;
    }

    // Single-character operators
    if ('!+-*/%<>'.includes(expr[i])) {
      tokens.push({ kind: 'OP', value: expr[i] });
      i++;
      continue;
    }

    throw new Error(`Unexpected character: ${expr[i]}`);
  }

  return tokens;
}

// ---------------------------------------------------------------------------
// Recursive-descent parser → AST
//
// Grammar (lowest → highest precedence):
//   expr        → logicalOr
//   logicalOr   → logicalAnd  ( '||' logicalAnd  )*
//   logicalAnd  → equality    ( '&&' equality    )*
//   equality    → relational  ( ('==='|'!=='|'=='|'!=') relational )*
//   relational  → additive    ( ('<'|'>'|'<='|'>=')     additive   )*
//   additive    → multiplicative ( ('+'|'-') multiplicative )*
//   multiplicative → unary    ( ('*'|'/'|'%') unary )*
//   unary       → ('!' | '-') unary | postfix
//   postfix     → primary ( '.' IDENT | '[' expr ']' )*
//   primary     → NUMBER | STRING | BOOL | NULL | IDENT | '(' expr ')'
// ---------------------------------------------------------------------------

function parse(expr) {
  const tokens = tokenise(expr);
  let pos = 0;

  function peek()    { return tokens[pos]; }
  function consume() { return tokens[pos++]; }
  function expect(kind, value) {
    const t = consume();
    if (t?.kind !== kind || (value !== undefined && t.value !== value))
      throw new Error(`Expected ${kind}${value !== undefined ? ' ' + value : ''}, got ${JSON.stringify(t)}`);
    return t;
  }

  function parseExpr()           { return parseLogicalOr(); }

  function parseLogicalOr() {
    let left = parseLogicalAnd();
    while (peek()?.kind === 'OP' && peek().value === '||') {
      consume();
      left = { type: 'BinaryExpr', op: '||', left, right: parseLogicalAnd() };
    }
    return left;
  }

  function parseLogicalAnd() {
    let left = parseEquality();
    while (peek()?.kind === 'OP' && peek().value === '&&') {
      consume();
      left = { type: 'BinaryExpr', op: '&&', left, right: parseEquality() };
    }
    return left;
  }

  function parseEquality() {
    let left = parseRelational();
    while (peek()?.kind === 'OP' && ['===', '!==', '==', '!='].includes(peek().value)) {
      const op = consume().value;
      left = { type: 'BinaryExpr', op, left, right: parseRelational() };
    }
    return left;
  }

  function parseRelational() {
    let left = parseAdditive();
    while (peek()?.kind === 'OP' && ['<', '>', '<=', '>='].includes(peek().value)) {
      const op = consume().value;
      left = { type: 'BinaryExpr', op, left, right: parseAdditive() };
    }
    return left;
  }

  function parseAdditive() {
    let left = parseMultiplicative();
    while (peek()?.kind === 'OP' && ['+', '-'].includes(peek().value)) {
      const op = consume().value;
      left = { type: 'BinaryExpr', op, left, right: parseMultiplicative() };
    }
    return left;
  }

  function parseMultiplicative() {
    let left = parseUnary();
    while (peek()?.kind === 'OP' && ['*', '/', '%'].includes(peek().value)) {
      const op = consume().value;
      left = { type: 'BinaryExpr', op, left, right: parseUnary() };
    }
    return left;
  }

  function parseUnary() {
    if (peek()?.kind === 'OP' && peek().value === '!') {
      consume();
      return { type: 'UnaryExpr', op: '!', operand: parseUnary() };
    }
    if (peek()?.kind === 'OP' && peek().value === '-') {
      consume();
      return { type: 'UnaryExpr', op: '-', operand: parseUnary() };
    }
    return parsePostfix();
  }

  function parsePostfix() {
    let node = parsePrimary();
    while (true) {
      if (peek()?.kind === 'DOT') {
        consume();
        const prop = expect('IDENT');
        node = { type: 'MemberExpr', object: node, property: prop.value, computed: false };
      } else if (peek()?.kind === 'LBRACK') {
        consume();
        const index = parseExpr();
        expect('RBRACK');
        node = { type: 'MemberExpr', object: node, property: index, computed: true };
      } else {
        break;
      }
    }
    return node;
  }

  function parsePrimary() {
    const t = peek();
    if (!t) throw new Error('Unexpected end of expression');

    if (t.kind === 'NUMBER') { consume(); return { type: 'Literal', value: t.value }; }
    if (t.kind === 'STRING') { consume(); return { type: 'Literal', value: t.value }; }
    if (t.kind === 'BOOL')   { consume(); return { type: 'Literal', value: t.value }; }
    if (t.kind === 'NULL')   { consume(); return { type: 'Literal', value: null    }; }

    if (t.kind === 'IDENT') {
      consume();
      return { type: 'Identifier', name: t.value };
    }

    if (t.kind === 'LPAREN') {
      consume();
      const inner = parseExpr();
      expect('RPAREN');
      return inner;
    }

    throw new Error(`Unexpected token: ${JSON.stringify(t)}`);
  }

  const ast = parseExpr();
  if (pos !== tokens.length)
    throw new Error(`Unexpected token after expression: ${JSON.stringify(tokens[pos])}`);
  return ast;
}

// ---------------------------------------------------------------------------
// AST interpreter
// ---------------------------------------------------------------------------

function interpret(node, scope) {
  switch (node.type) {
    case 'Literal':
      return node.value;

    case 'Identifier': {
      if (!(node.name in scope))
        throw new Error(`Unknown identifier: ${node.name}`);
      return scope[node.name];
    }

    case 'MemberExpr': {
      const obj = interpret(node.object, scope);
      if (obj === null || obj === undefined)
        throw new Error('Cannot read property of null/undefined');
      const key = node.computed
        ? interpret(node.property, scope)
        : node.property;
      // Only allow plain own/prototype-chain data properties; block
      // dangerous built-ins such as constructor, __proto__, prototype.
      if (typeof key === 'string' && /^(__proto__|constructor|prototype)$/.test(key))
        throw new Error(`Access to property "${key}" is not allowed`);
      return obj[key];
    }

    case 'UnaryExpr': {
      const v = interpret(node.operand, scope);
      if (node.op === '!')  return !v;
      if (node.op === '-')  return -v;
      throw new Error(`Unknown unary operator: ${node.op}`);
    }

    case 'BinaryExpr': {
      // Short-circuit logical operators
      if (node.op === '&&') return interpret(node.left, scope) && interpret(node.right, scope);
      if (node.op === '||') return interpret(node.left, scope) || interpret(node.right, scope);

      const l = interpret(node.left,  scope);
      const r = interpret(node.right, scope);

      switch (node.op) {
        case '===': return l === r;
        case '!==': return l !== r;
        case '==':  return l == r;   // eslint-disable-line eqeqeq
        case '!=':  return l != r;   // eslint-disable-line eqeqeq
        case '<':   return l <   r;
        case '>':   return l >   r;
        case '<=':  return l <=  r;
        case '>=':  return l >=  r;
        case '+':   return l +   r;
        case '-':   return l -   r;
        case '*':   return l *   r;
        case '/':   return l /   r;
        case '%':   return l %   r;
        default:    throw new Error(`Unknown binary operator: ${node.op}`);
      }
    }

    default:
      throw new Error(`Unknown AST node type: ${node.type}`);
  }
}

// ---------------------------------------------------------------------------
// Public evalRule — safe drop-in for the reference implementation
//
// Exposed scope variables:
//   ctx  — req.body.context  (the data object callers write rules against)
//
// Example rules:
//   "ctx.amount > 100"
//   "ctx.role === 'admin' && ctx.active"
//   "ctx.score >= 90 || ctx.override === true"
// ---------------------------------------------------------------------------

function evalRule(req) {
  const expr = req.body?.rule;
  if (typeof expr !== 'string' || expr.trim() === '')
    throw new Error('req.body.rule must be a non-empty string');

  const ctx  = req.body?.context ?? {};
  const ast  = parse(expr);
  return interpret(ast, { ctx });
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------

app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: '`rule` must be a non-empty string' });
  }

  if (context === undefined || context === null || typeof context !== 'object') {
    return res.status(400).json({ error: '`context` must be a non-null object' });
  }

  let result;
  try {
    result = evalRule(req);
  } catch (err) {
    return res.status(400).json({ error: `Rule evaluation failed: ${err.message}` });
  }

  return res.status(200).json({ result: !!result });
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`acme-rules listening on port ${PORT}`));

module.exports = { app, evalRule, parse, interpret }; // export for testing

