// ── inline the pure logic (no express needed) ──────────────────────────────
$(sed -n '/^function tokenise/,/^module\.exports/{ /^app\./d; /^module\.exports/d; p }' app.js)

// ── test cases ──────────────────────────────────────────────────────────────
const tests = [
  // basic comparisons
  { rule: 'ctx.amount > 100',                ctx: { amount: 150 },             want: true  },
  { rule: 'ctx.amount > 100',                ctx: { amount: 50  },             want: false },
  { rule: \"ctx.status == 'active'\",          ctx: { status: 'active' },        want: true  },
  { rule: \"ctx.status == 'active'\",          ctx: { status: 'inactive' },      want: false },
  { rule: 'ctx.score >= 90',                 ctx: { score: 90 },               want: true  },
  { rule: 'ctx.score <= 89',                 ctx: { score: 90 },               want: false },
  { rule: 'ctx.x != 5',                      ctx: { x: 5 },                    want: false },
  // logic
  { rule: 'ctx.a > 1 && ctx.b < 10',         ctx: { a: 2,  b: 5  },           want: true  },
  { rule: 'ctx.a > 1 && ctx.b < 10',         ctx: { a: 0,  b: 5  },           want: false },
  { rule: 'ctx.a > 1 || ctx.b < 10',         ctx: { a: 0,  b: 5  },           want: true  },
  // grouping
  { rule: '(ctx.a > 1 || ctx.b > 1) && ctx.c == true',
                                              ctx: { a: 0, b: 2, c: true },    want: true  },
  // bool literals
  { rule: 'ctx.flag == true',                ctx: { flag: true  },             want: true  },
  { rule: 'ctx.flag == false',               ctx: { flag: true  },             want: false },
  // missing key → undefined  → false comparison
  { rule: 'ctx.missing > 0',                 ctx: {},                          want: false },

  // ── SECURITY: all of these MUST throw / return null ──────────────────────
  { rule: \"require('fs')\",                   ctx: {},  wantError: true },
  { rule: 'process.env',                      ctx: {},  wantError: true },
  { rule: 'ctx.__proto__',                    ctx: {},  wantError: true },
  { rule: '1; process.exit(1)',               ctx: {},  wantError: true },
  { rule: 'ctx.x > 1 ++ ctx.y',              ctx: {},  wantError: true },
];

let passed = 0, failed = 0;
for (const t of tests) {
  try {
    const result = evalRule(t.rule, t.ctx);
    if (t.wantError) {
      console.error('FAIL (expected error but got result)', t.rule, '->', result);
      failed++;
    } else if (result === t.want) {
      console.log('PASS', t.rule);
      passed++;
    } else {
      console.error('FAIL', t.rule, '-> got', result, 'want', t.want);
      failed++;
    }
  } catch (e) {
    if (t.wantError) {
      console.log('PASS (correctly rejected):', t.rule, '->', e.message);
      passed++;
    } else {
      console.error('FAIL (unexpected error):', t.rule, '->', e.message);
      failed++;
    }
  }
}
console.log(\`\nResults: \${passed} passed, \${failed} failed\`);
process.exit(failed > 0 ? 1 : 0);
